// === Tab: tab2 ===
class particleGenerator {
  ArrayList<Particle> particles;
  emitPos;

  constructor(x, y) {
    emitPos = new PVector(x, y);
    particles = new ArrayList<Particle>();
  }

  function run() {
    // limit particle generation frequency
    if (frameCount % 60 == 0) {
      particles.add(new Particle(emitPos));
    }
    for (i = particles.size ()-1; i >= 0; i--) {
      let p = particles.get(i);
      p.run();
      if (p.pos.y > height + 35) {
        particles.remove(i);
      }
    }
  }
}

// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

class Particle {
  pos, vel;
  numFaces = 22;
  let faces = new Array(numFaces);
  let gap = random(10), incr;

  constructor(v) {
    vel = new PVector(0, .75);
    pos = v.get();
    for (i = 0; i < numFaces; i++) {
      faces[i] = new Face();
    }
  }

  function run() {
    pos.add(vel);
    incr = gap;
    for (i = 0; i < numFaces; i++) {
      faces[i].drawFace(pos.x + incr, pos.y);
      incr += 40 + gap;
    }
  }
}

// %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

class Face {
  faceXrad, faceYrad, eyerad, pupilrad, 
  eyeY, mouthY, h, hlfMouthWdth, tilt, alpha, movePupilX;

  constructor() {
    faceXrad = random(10, 25);
    faceYrad = random(10, 35);
    eyerad = random(2, 8);
    pupilrad = random(.5, eyerad-1);
    eyeY = random(faceYrad) + eyerad;
    mouthY = (random((faceYrad-eyerad)/2.0));
    hlfMouthWdth = faceXrad - (mouthY/(faceYrad/faceXrad));
    h = random(360);
    tilt = alpha = 0;
  }

  function drawFace(cx, cy) { 
    tilt += .005;
    if (tilt > 1) tilt = 1;
    alpha += .45;
    if (alpha > 100) alpha = 100;
    strokeWeight(2);
    stroke(0, alpha);
    fill(h, 50, 100, alpha);
    ellipse(cx, cy, faceXrad, faceYrad* tilt);
    strokeWeight(1);
    fill(360, alpha);
    ellipse(cx-10, cy-eyeY* tilt, eyerad, eyerad* tilt);
    ellipse(cx +10, cy-eyeY* tilt, eyerad, eyerad* tilt);
    fill(0, alpha);
    movePupilX = 4 * sin(frameCount * .02);
    ellipse(cx-10+movePupilX, cy-eyeY* tilt, pupilrad, pupilrad* tilt);
    ellipse(cx+10+movePupilX, cy-eyeY* tilt, pupilrad, pupilrad* tilt);
    line(cx-hlfMouthWdth, cy+(mouthY* tilt), cx+hlfMouthWdth, cy + (mouthY * tilt));
  }
}

